class _Path0Painter extends CustomPainter {
  const _Path0Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(487, 0);
    path.lineTo(487, 246);
    path.lineTo(0, 246);
    path.lineTo(0, 0);
    path.close();
    canvas.drawPath(path, Paint()..color = Color(0xFFFFDF25));
  }

  @override
  bool shouldRepaint(_Path0Painter oldDelegate) => false;
}
